import type { ReactNode } from "react";

import { IconArrowUpRight } from "@rhs-ui/icons";
import { cn } from "@/lib/utils";

export interface CaseStudy {
  href: string;
  company: string;
  /** The company's logo or mark, small. */
  logo?: ReactNode;
  /** The headline result, large: "3x", "-40%". */
  metric: string;
  metricLabel: string;
  summary: string;
  image?: ReactNode;
}

export interface CaseStudyCardsProps {
  title: string;
  description?: string;
  studies: readonly CaseStudy[];
  className?: string;
}

/**
 * Customer stories as cards that lead with the number: picture, the result
 * large, what it means, and who. Each card is one link to the full story.
 */
export function CaseStudyCards({ title, description, studies, className }: CaseStudyCardsProps) {
  return (
    <section data-slot="case-study-cards" className={cn("py-16 sm:py-24", className)}>
      <div className="max-w-2xl">
        <h2 className="text-3xl font-medium tracking-[-.04em] text-balance sm:text-4xl">{title}</h2>
        {description ? <p className="mt-4 text-base leading-relaxed text-muted-foreground">{description}</p> : null}
      </div>
      <ul className="mt-12 grid gap-6 md:grid-cols-3">
        {studies.map((study) => (
          <li key={`${study.href}-${study.company}`}>
            <a href={study.href} className="group flex h-full flex-col overflow-hidden rounded-3xl border border-border outline-none focus-visible:ring-[3px] focus-visible:ring-ring/40">
              {study.image ? <span className="block aspect-[16/10] overflow-hidden bg-muted [&_img]:size-full [&_img]:object-cover [&_img]:transition-transform [&_img]:duration-500 group-hover:[&_img]:scale-[1.03] motion-reduce:[&_img]:transition-none">{study.image}</span> : null}
              <span className="flex flex-1 flex-col p-6">
                <span className="text-4xl font-medium tracking-[-.05em] tabular-nums">{study.metric}</span>
                <span className="mt-1 text-sm text-muted-foreground">{study.metricLabel}</span>
                <span className="mt-5 flex-1 text-sm leading-relaxed">{study.summary}</span>
                <span className="mt-6 flex items-center justify-between border-t border-border pt-4 text-sm font-medium">
                  <span className="flex items-center gap-2 [&_svg]:size-5">{study.logo}{study.company}</span>
                  <IconArrowUpRight aria-hidden="true" className="size-4 transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5 motion-reduce:transition-none" />
                </span>
              </span>
            </a>
          </li>
        ))}
      </ul>
    </section>
  );
}
